here = fileparts(fileparts(mfilename('fullpath'))); addpath(here); addpath([here '/em']);
R('linReach 1D', ['f=@(x,u) 1-(1001/750)*x(1)+(1001/3000)*x(1)^4+0*u(1); sys=nonlinearSys(f,1,1); params.R0=zonotope(0); params.U=zonotope(0); params.tFinal=2;' ...
 'options.timeStep=2; options.alg=''lin''; options.tensorOrder=3; options.errorOrder=10; options.taylorTerms=10; options.zonotopeOrder=20; try, R=reach(sys,params,options); catch ME, out=char(ME.message); return; end;' ...
 '[t,x]=ode45(@(t,x) f(x,0),[0 0.25],0); I=interval(R.timeInterval.set{1}); out=sprintf("Rti = [%g,%g]; x(1/4) = %g inside = %d",I.inf,I.sup,x(end),contains(R.timeInterval.set{1},x(end)));']);
